		kind, name, ok = rAssignmentEntity(node, src, scope)
		if !ok {
			return Entity{}, false
		}
	case "function_definition":
		// In R, function_definition is anonymous — the name lives on the
		// enclosing assignment (the binary_operator case above); extracting
